import bpy,json,importlib.util
from pathlib import Path
root=Path(bpy.data.filepath).parent.parent
out={}
for col,names in [('Boat_Workshop',['Side strake 00','Continuous shaped gunwale','Floorboard 00','End thwart 00','Inner rib 00 -1']),('Shipyard_COMBINED_Craft',['Combined_front_A terrace paving','Combined_rear_B workshop footing'])]:
 for o in bpy.data.collections[col].objects:
  if o.name in names:
   out[o.name]={'matrix':[list(r) for r in o.matrix_world],'verts':[list(v.co) for v in o.data.vertices[:12]],'uv_samples':[list(v.uv) for v in o.data.uv_layers.active.data[:16]] if o.data.uv_layers.active else [],'uv_range':[[min(v.uv[i] for v in o.data.uv_layers.active.data),max(v.uv[i] for v in o.data.uv_layers.active.data)] for i in range(2)] if o.data.uv_layers.active else [],'attributes':list(o.keys())}
out['packages']={m:bool(importlib.util.find_spec(m)) for m in ['numpy','PIL']}
(root/'captures/surface_pass_20261113/uv_probe.json').write_text(json.dumps(out,indent=2),encoding='utf8')
print(json.dumps(out))
